1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Circle Display</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	    html, body {
14	      width: 100%;
15	      height: 100%;
16	      overflow: hidden;
17	    }
18	    body {
19	      display: flex;
20	      flex-direction: column;
21	      justify-content: center;
22	      align-items: center;
23	      gap: 20px;
24	      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
25	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
26	      color: white;
27	      font-size: 14px;
28	      text-align: center;
29	      padding: 20px;
30	    }
31	    .circle-container {
32	      cursor: pointer;
33	      border: none;
34	      background: none;
35	      padding: 0;
36	      position: relative;
37	      will-change: transform;
38	    }
39	    .circle-container:hover,
40	    .circle-container:focus-visible {
41	      transform: scale(1.08);
42	    }
43	    .circle-container:focus {
44	      outline: none;
45	    }
46	    .circle-container:focus-visible {
47	      outline: 3px solid rgba(255, 255, 255, 0.7);
48	      outline-offset: 12px;
49	      border-radius: 50%;
50	    }
51	    svg {
52	      width: min(400px, 80vw);
53	      height: min(400px, 80vw);
54	      display: block;
55	      animation: fadeIn 0.6s ease-out;
56	    }
57	    circle {
58	      fill: #ffffff;
59	      stroke: rgba(255, 255, 255, 0.2);
60	      stroke-width: 2;
61	      animation: pulse 3s ease-in-out infinite;
62	      filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.3));
63	      transition: fill 0.3s ease, r 0.3s ease, stroke 0.3s ease, filter 0.3s ease;
64	    }
65	    .circle-container:hover circle,
66	    .circle-container:focus-visible circle {
67	      fill: #e8f4f8;
68	      r: 205;
69	      stroke: rgba(255, 255, 255, 0.4);
70	    }
71	    .circle-container.active circle {
72	      fill: #ffd700;
73	      stroke: rgba(255, 215, 0, 0.3);
74	      animation: pulse-active 0.6s ease-in-out;
75	      filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
76	    }
77	    .circle-container.active:hover circle {
78	      fill: #ffed4e;
79	    }
80	    .color-modes {
81	      --color-pink: #ff6b9d;
82	      --color-teal: #4ecdc4;
83	      --color-mint: #95e1d3;
84	    }
85	    .circle-container.color-mode-1 circle {
86	      fill: var(--color-pink);
87	      filter: drop-shadow(0 20px 40px rgba(255, 107, 157, 0.3));
88	    }
89	    .circle-container.color-mode-1.active circle {
90	      filter: drop-shadow(0 20px 40px rgba(255, 107, 157, 0.5));
91	    }
92	    .circle-container.color-mode-2 circle {
93	      fill: var(--color-teal);
94	      filter: drop-shadow(0 20px 40px rgba(78, 205, 196, 0.3));
95	    }
96	    .circle-container.color-mode-2.active circle {
97	      filter: drop-shadow(0 20px 40px rgba(78, 205, 196, 0.5));
98	    }
99	    .circle-container.color-mode-3 circle {
100	      fill: var(--color-mint);
101	      filter: drop-shadow(0 20px 40px rgba(149, 225, 211, 0.3));
102	    }
103	    .circle-container.color-mode-3.active circle {
104	      filter: drop-shadow(0 20px 40px rgba(149, 225, 211, 0.5));
105	    }
106	    .hint {
107	      font-size: 12px;
108	      opacity: 0.85;
109	      transition: opacity 0.3s ease;
110	      letter-spacing: 0.5px;
111	      max-width: 90%;
112	    }
113	    .circle-container:hover ~ .hint,
114	    .circle-container:focus-visible ~ .hint {
115	      opacity: 1;
116	    }
117	    .mode-indicator {
118	      font-size: 10px;
119	      opacity: 0;
120	      margin-top: 8px;
121	      letter-spacing: 1px;
122	      text-transform: uppercase;
123	      transition: opacity 0.3s ease;
124	      height: 16px;
125	    }
126	    .mode-indicator.visible {
127	      opacity: 0.9;
128	    }
129	    @keyframes pulse {
130	      0%, 100% { r: 200; }
131	      50% { r: 202; }
132	    }
133	    @keyframes pulse-active {
134	      0% { r: 200; }
135	      50% { r: 210; }
136	      100% { r: 200; }
137	    }
138	    @keyframes fadeIn {
139	      from { opacity: 0; transform: scale(0.9); }
140	      to { opacity: 1; transform: scale(1); }
141	    }
142	    @media (max-width: 480px) {
143	      body {
144	        gap: 16px;
145	      }
146	      .hint {
147	        font-size: 11px;
148	      }
149	      .mode-indicator {
150	        font-size: 9px;
151	      }
152	    }
153	    @media (prefers-reduced-motion: reduce) {
154	      * {
155	        animation: none !important;
156	        transition: none !important;
157	      }
158	    }
159	  </style>
160	</head>
161	<body>
162	  <main style="text-align: center;">
163	    <button class="circle-container" id="decorative-circle" aria-label="Interactive circle - click to toggle">
164	      <svg viewBox="0 0 400 400" aria-hidden="true">
165	        <circle cx="200" cy="200" r="200"/>
166	      </svg>
167	    </button>
168	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
169	  </main>
170	  <div class="hint" id="hint-text" role="status" aria-live="polite">Click to activate • Double-click to change color</div>
171	
172	  <script>
173	    const STORAGE_KEY = 'circle-state';
174	    const COLOR_MODES = ['default', 'color-mode-1', 'color-mode-2', 'color-mode-3'];
175	    const COLOR_NAMES = ['Default White', 'Pink', 'Teal', 'Mint'];
176	
177	    const circle = document.getElementById('decorative-circle');
178	    const hint = document.getElementById('hint-text');
179	    const modeIndicator = document.getElementById('mode-indicator');
180	
181	    let state = { active: false, colorMode: 0 };
182	
183	    const saveState = () => localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
184	
185	    const loadState = () => {
186	      try {
187	        const saved = localStorage.getItem(STORAGE_KEY);
188	        if (saved) state = JSON.parse(saved);
189	      } catch (e) {
190	        console.warn('Failed to load state');
191	      }
192	      applyState();
193	    };
194	
195	    const applyState = () => {
196	      circle.classList.remove('active', ...COLOR_MODES);
197	      if (state.active) circle.classList.add('active');
198	      if (state.colorMode > 0) circle.classList.add(COLOR_MODES[state.colorMode]);
199	      updateUI();
200	    };
201	
202	    const toggleActive = () => {
203	      state.active = !state.active;
204	      applyState();
205	      saveState();
206	    };
207	
208	    const cycleColor = () => {
209	      state.colorMode = (state.colorMode + 1) % COLOR_MODES.length;
210	      state.active = true;
211	      applyState();
212	      saveState();
213	    };
214	
215	    const resetState = () => {
216	      state = { active: false, colorMode: 0 };
217	      applyState();
218	      saveState();
219	    };
220	
221	    const updateHint = () => {
222	      if (state.active) {
223	        hint.textContent = 'Active! • Double-click or press C to cycle color • Press R to reset';
224	      } else {
225	        hint.textContent = 'Click to activate • Double-click to change color • C to cycle • R to reset';
226	      }
227	    };
228	
229	    const updateModeIndicator = () => {
230	      if (state.active && state.colorMode > 0) {
231	        modeIndicator.textContent = COLOR_NAMES[state.colorMode];
232	        modeIndicator.classList.add('visible');
233	      } else {
234	        modeIndicator.classList.remove('visible');
235	      }
236	    };
237	
238	    const updateUI = () => {
239	      updateHint();
240	      updateModeIndicator();
241	    };
242	
243	    circle.addEventListener('click', toggleActive);
244	    circle.addEventListener('dblclick', (e) => {
245	      e.preventDefault();
246	      cycleColor();
247	    });
248	
249	    circle.addEventListener('keydown', (e) => {
250	      const key = e.key.toLowerCase();
251	      if (key === ' ' || key === 'enter') {
252	        e.preventDefault();
253	        toggleActive();
254	      } else if (key === 'c') {
255	        e.preventDefault();
256	        cycleColor();
257	      } else if (key === 'r') {
258	        e.preventDefault();
259	        resetState();
260	      }
261	    });
262	
263	    circle.addEventListener('mouseenter', () => {
264	      if (!state.active) {
265	        hint.textContent = 'Click to activate • Double-click or C to cycle color • R to reset';
266	      }
267	    });
268	
269	    circle.addEventListener('mouseleave', updateHint);
270	
271	    loadState();
272	    circle.focus();
273	  </script>
274	</body>
275	</html>
